// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Ok, implement all, remove things made redundant by this change"
// Changes: Emit only the typed Boolean-to-string operation.
#include "codegen_internal.h"

void cg_print_bool_to_string(Ctx* ctx,
                             FILE* out,
                             const CgPlacement* placement,
                             IrInstruction* inst) {
  if (inst->result == IR_INVALID_ID)
    return;

  ctx->cg_state.builtin_label_id++;

  fprintf(out, "JUMPIFEQ $cg_tostr_btrue_%zu ", ctx->cg_state.builtin_label_id);
  cg_print_operand(out, placement, &inst->operands.unary.operand);
  fputs(" bool@true\nMOVE ", out);
  cg_print_value(out, placement, inst->result);
  fprintf(out, " string@false\nJUMP $cg_tostr_end_%zu\n",
          ctx->cg_state.builtin_label_id);
  fprintf(out, "LABEL $cg_tostr_btrue_%zu\nMOVE ",
          ctx->cg_state.builtin_label_id);
  cg_print_value(out, placement, inst->result);
  fprintf(out, " string@true\nLABEL $cg_tostr_end_%zu\n",
          ctx->cg_state.builtin_label_id);
}
